import{_ as t,o as i,c as n,ah as r}from"./chunks/framework.D4KxWb5R.js";const g=JSON.parse('{"title":"Registre : produits et zones","description":"","frontmatter":{},"headers":[],"relativePath":"guide/administration/registry.md","filePath":"src/guide/administration/registry.md"}'),o={name:"guide/administration/registry.md"};function s(a,e,l,u,d,c){return i(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="registre-produits-et-zones" tabindex="-1">Registre : produits et zones <a class="header-anchor" href="#registre-produits-et-zones" aria-label="Permalink to &quot;Registre : produits et zones&quot;">​</a></h1><p>Le registre recense les produits de M&#39;City et les zones où ils sont présents. Il alimente les landing pages du site, la page « Nos zones » et les espaces produits de l&#39;intranet. <strong>Produits</strong> et <strong>Zones</strong> sont ouverts au PDG et au Pôle Exploitation ; l&#39;intégration technique d&#39;un produit est réservée au PDG.</p><p>Rien ne se supprime : un produit ou une zone inactif passe hors ligne et garde son historique.</p><h2 id="zones" tabindex="-1">Zones <a class="header-anchor" href="#zones" aria-label="Permalink to &quot;Zones&quot;">​</a></h2><p>Qualifier une zone <strong>enregistre une décision</strong> prise par M&#39;City hors de la plateforme, à l&#39;issue de la fiche de zone. La plateforme ne vérifie ni ne calcule rien, et ne stocke jamais la fiche elle-même.</p><ol><li><strong>Zones → Nouvelle zone</strong> (ou ouvrez une zone).</li><li>Renseignez le <strong>nom</strong> et la <strong>région</strong>.</li><li>Pour une zone qualifiée : passez la <strong>qualification</strong> à <strong>Qualifiée</strong>, puis choisissez le <strong>type de zone</strong> (ville en croissance, ville structurée, zone périurbaine) et saisissez la <strong>description publique</strong>, au moins en anglais.</li><li>Ajoutez si vous le souhaitez une photo (JPG, PNG ou WebP, 2 Mo au plus), affichée en tête de la carte de la zone sur le site.</li><li>Enregistrez.</li></ol><p>Une zone qualifiée et active apparaît sur « Nos zones » et devient rattachable à un produit. Une zone <strong>inactive</strong> est masquée du site.</p><p>Une zone rattachée à un produit actif ne peut être ni déqualifiée ni désactivée : détachez-la d&#39;abord du produit.</p><h2 id="produits" tabindex="-1">Produits <a class="header-anchor" href="#produits" aria-label="Permalink to &quot;Produits&quot;">​</a></h2><h3 id="enregistrer-un-produit" tabindex="-1">Enregistrer un produit <a class="header-anchor" href="#enregistrer-un-produit" aria-label="Permalink to &quot;Enregistrer un produit&quot;">​</a></h3><ol><li><strong>Produits → Nouveau produit</strong>.</li><li><strong>Identité</strong> : nom, identifiant d&#39;URL (la landing page sera à <code>/products/&lt;identifiant&gt;</code>), statut, logo (PNG, JPG ou WebP, 2 Mo au plus), couleurs principale et secondaire, lien d&#39;accès (application ou site), adresse du back-office, langues supportées par le produit (codes ISO séparés par des virgules, ex. <code>en, fr, pt</code>).</li><li><strong>Contenu de la landing page</strong>, en anglais et en français : accroche, présentation, « Pour qui ? », fonctionnalités clés, étapes « Comment ça marche », contact propre au produit, mentions légales.</li><li><strong>Visuels</strong> : ajoutez les images de la landing page (PNG, JPG ou WebP, 5 Mo au plus chacune).</li><li><strong>Zones</strong> : cochez les zones où le produit est présent. Seules les zones qualifiées et actives sont proposées.</li><li><strong>Équipes responsables</strong> : cochez les <a href="./teams.html">équipes</a> du produit.</li><li><strong>Créer le produit</strong>.</li></ol><p>L&#39;enregistrement crée automatiquement la landing page sur le site public et l&#39;espace du produit dans l&#39;intranet.</p><ul><li>Un produit <strong>Actif (en ligne)</strong> doit avoir au moins son accroche en anglais.</li><li>Un produit <strong>Inactif (hors ligne)</strong> peut rester incomplet ; sa landing page n&#39;est plus publiée.</li><li>L&#39;adresse du back-office n&#39;est jamais affichée sur le site public : elle sert au bouton <strong>Ouvrir le back-office</strong> de l&#39;intranet.</li></ul><h3 id="modifier-un-produit" tabindex="-1">Modifier un produit <a class="header-anchor" href="#modifier-un-produit" aria-label="Permalink to &quot;Modifier un produit&quot;">​</a></h3><p>Ouvrez le produit, modifiez, enregistrez. Si quelqu&#39;un a enregistré la même fiche entre-temps, votre enregistrement est refusé : rechargez la page et refaites votre modification.</p><p>Chaque enregistrement est envoyé automatiquement au back-office du produit s&#39;il est intégré.</p><h3 id="statut-de-synchronisation" tabindex="-1">Statut de synchronisation <a class="header-anchor" href="#statut-de-synchronisation" aria-label="Permalink to &quot;Statut de synchronisation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Statut</th><th>Signification</th></tr></thead><tbody><tr><td>Synchronisé</td><td>Le back-office a reçu la dernière version de la fiche.</td></tr><tr><td>En attente</td><td>Un envoi est en cours ou va être retenté.</td></tr><tr><td>Désynchronisé</td><td>Les envois ont échoué après le nombre de tentatives fixé dans la <a href="./settings.html">configuration</a>. Le PDG et les équipes du produit sont alertés.</td></tr><tr><td>Non intégré</td><td>Le back-office ne reçoit pas encore la fiche : rapprochement manuel.</td></tr></tbody></table><p>En cas de désynchronisation, vérifiez avec l&#39;équipe du produit que son back-office répond, puis <strong>Resynchroniser</strong> depuis la page <strong>Intégration API</strong>.</p><h2 id="integration-d-un-produit" tabindex="-1">Intégration d&#39;un produit <a class="header-anchor" href="#integration-d-un-produit" aria-label="Permalink to &quot;Intégration d&#39;un produit&quot;">​</a></h2><p>Réservée au PDG, depuis la fiche du produit. Les détails techniques à transmettre à l&#39;équipe du produit sont dans <a href="./../integration/overview.html">Intégration technique</a>.</p><h3 id="integration-sso" tabindex="-1">Intégration SSO <a class="header-anchor" href="#integration-sso" aria-label="Permalink to &quot;Intégration SSO&quot;">​</a></h3><p>Permet aux comptes M&#39;City d&#39;ouvrir le back-office du produit avec leur compte.</p><ol><li>Fiche du produit → <strong>Intégration SSO</strong>.</li><li>Saisissez les <strong>URI de redirection</strong> fournies par l&#39;équipe du produit (HTTPS, une par ligne, 5 au plus) et, si elle en a une, l&#39;<strong>URI de déconnexion (back-channel)</strong>.</li><li><strong>Créer le client</strong>.</li><li>Copiez le <strong>secret du client</strong> : il n&#39;est affiché qu&#39;une fois. Transmettez-le à l&#39;équipe du produit par un canal sûr, avec l&#39;identifiant client et l&#39;URL de découverte affichés sur la page.</li></ol><p><strong>Régénérer le secret</strong> l&#39;invalide aussitôt : le back-office ne connecte plus personne tant qu&#39;il n&#39;a pas le nouveau.</p><h3 id="integration-api" tabindex="-1">Intégration API <a class="header-anchor" href="#integration-api" aria-label="Permalink to &quot;Intégration API&quot;">​</a></h3><p>Permet au back-office de lire et mettre à jour sa fiche, de remonter ses indicateurs, et de recevoir chaque modification de la fiche.</p><ol><li>Fiche du produit → <strong>Intégration API</strong>.</li><li><strong>Générer le jeton</strong> de service, copiez-le (affiché une seule fois) et transmettez-le par un canal sûr.</li><li>Saisissez l&#39;<strong>URL du webhook</strong> fournie par l&#39;équipe du produit et enregistrez : le <strong>secret du webhook</strong> est créé et affiché une seule fois ; transmettez-le aussi.</li><li>Choisissez le <strong>mode de remontée</strong> des indicateurs : envoi par le produit (API) ou relevé horaire par M&#39;City, ou le mode par défaut de la configuration.</li></ol><p>La page montre aussi l&#39;état de synchronisation, les derniers échanges, et deux actions : <strong>Resynchroniser</strong> (renvoie la fiche) et <strong>Relever maintenant</strong> (collecte les indicateurs en mode relevé).</p><p>Régénérer le jeton ou le secret du webhook invalide aussitôt l&#39;ancien.</p>',30)])])}const h=t(o,[["render",s]]);export{g as __pageData,h as default};
